UPDATE TB_BANNER_POPUP SET
    POPUP_TYPE = #{popupType}, CATEGORY = #{category}, CHANNELS = #{channels}, TITLE = #{title}, CONTENT = #{content},
    IMAGE_URL = #{imageUrl}, ALT_TEXT = #{altText}, LINK_URL = #{linkUrl}, BG_COLOR = #{bgColor},
    START_AT = #{startAt}, END_AT = #{endAt}, DISPLAY_ORDER = #{displayOrder}, USE_YN = #{useYn},
    REG_AT = #{regAt}, REG_BY = #{regBy}, UPD_AT = #{updAt}, UPD_BY = #{updBy}
WHERE BANNER_ID = #{bannerId}
